# G4-C7 M37-P2: LOCAL AI paired native Blender operator technical study (NOT ART).
# One explicitly user-launched call, NO Work, no code generated by model executed.
# Does not edit open Blender GUI, source v3, Minecraft, GitHub or main.
[CmdletBinding()]
param(
    [string]$Model = "qwen3:14b",
    [string]$SessionRoot = "",
    [string]$BlenderExe = "",
    [switch]$PrepareOnly,
    [switch]$ExplicitTechOnly
)
# First real native Cycles visual inspection showed two unadorned cubes,
# no city / factory / lived interiors. Default user execution must STOP.
if (-not $PrepareOnly -and -not $ExplicitTechOnly) {
    Write-Host "G4C7_P2_VISUAL_ART_REJECT: 3 real Cycles views contained only 2 cubes."
    Write-Host "The model-assisted operator loop is TECH ONLY; user art launch is disabled."
    Write-Host "No Ollama request was made; no Blender files or Minecraft were changed."
    exit 2
}
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$sha = "536e451c763c4326421b13285abf1056a3a11d755028f8ff20b54b99b08a0249"
$repo = "ryomashibaba/makecode-limitlab"
# Immutable code snapshot with all 3 scripts; never use branch's changing HEAD.
$codeCommit = "f13f8ecc4029ca824e1a343d58f02b20f388481d"

function Get-HexHash([string]$File) {
    return (Get-FileHash -LiteralPath $File -Algorithm SHA256).Hash.ToLowerInvariant()
}
function Find-V3Studio([string]$Folder) {
    if (-not (Test-Path -LiteralPath $Folder -PathType Container)) {
        throw "P2_AUTHOR_SESSIONS_NOT_FOUND"
    }
    $dirs = @(Get-ChildItem -LiteralPath $Folder -Directory | Sort-Object LastWriteTime -Descending)
    foreach ($d in $dirs) {
        $v3 = Join-Path $d.FullName "P2_DIRECT_AUTHOR_UNAPPROVED.blend"
        if ((Test-Path -LiteralPath $v3 -PathType Leaf) -and ((Get-HexHash $v3) -eq $sha)) {
            return [pscustomobject]@{ File = $v3; Folder = $d.FullName }
        }
    }
    throw "VERIFIED_UNMODIFIED_V3_COPY_NOT_FOUND"
}
function Find-BlenderBinary([string]$Selected) {
    if ($Selected) {
        if (-not (Test-Path -LiteralPath $Selected -PathType Leaf)) {throw "BLENDER_EXE_NOT_FOUND"}
        return (Resolve-Path -LiteralPath $Selected).Path
    }
    $results = @()
    foreach ($root in @($env:ProgramFiles, [Environment]::GetFolderPath("ProgramFilesX86"))) {
        if (-not $root) {continue}
        $dir = Join-Path $root "Blender Foundation"
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) {continue}
        $results += @(Get-ChildItem -LiteralPath $dir -Directory |
            ForEach-Object {
                $exe = Join-Path $_.FullName "blender.exe"
                if (Test-Path -LiteralPath $exe -PathType Leaf) {
                    [pscustomobject]@{ File=$exe; Version=$_.Name }
                }
            })
    }
    if ($results.Count -gt 0) {
        return (@($results | Sort-Object Version -Descending)[0]).File
    }
    $cmd = Get-Command blender.exe -ErrorAction SilentlyContinue
    if ($cmd -and $cmd.Source) {return $cmd.Source}
    throw "BLENDER_NOT_FOUND"
}
function Find-HostPython {
    $cmd = Get-Command py.exe -ErrorAction SilentlyContinue
    if ($cmd -and $cmd.Source) {return [pscustomobject]@{ Exe=$cmd.Source; Prefix=@("-3") }}
    $cmd = Get-Command python.exe -ErrorAction SilentlyContinue
    if ($cmd -and $cmd.Source) {return [pscustomobject]@{ Exe=$cmd.Source; Prefix=@() }}
    throw "PYTHON_NOT_FOUND"
}
function Open-Evidence([string]$Folder) {
    if (Test-Path -LiteralPath $Folder -PathType Container) {
        try {Start-Process explorer.exe -ArgumentList ('"{0}"' -f $Folder) | Out-Null} catch {}
    }
}
try {
    if (-not $SessionRoot) {
        $SessionRoot = Join-Path ([Environment]::GetFolderPath("MyDocuments")) "G4C7\P2_Author_Sessions"
    }
    $studio = Find-V3Studio $SessionRoot
    $blender = Find-BlenderBinary $BlenderExe
    $python = Find-HostPython

    $suffix = [Guid]::NewGuid().ToString("N").Substring(0,6)
    $trial = Join-Path $studio.Folder ("LOCAL_AI_NATIVE_PAIRED_OPERATOR_" + (Get-Date -Format "yyyyMMdd_HHmmss") + "_" + $suffix)
    New-Item -ItemType Directory -Path $trial -ErrorAction Stop | Out-Null

    $paths = [ordered]@{
        operator="g4c7_m37p2_native_operator_author.py"
        propose="g4c7_m37p2_ollama_paired_native_action_proposal.py"
        review="g4c7_m37p2_paired_operator_three_view_evidence.py"
    }
    [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
    foreach ($key in @($paths.Keys)) {
        $file=$paths[$key]
        $url="https://raw.githubusercontent.com/$repo/$codeCommit/tools/$file"
        Invoke-WebRequest -Uri $url -OutFile (Join-Path $trial $file) -UseBasicParsing
    }

    $manifest = [ordered]@{
        schema="g4c7-m37p2-paired-operator-local-trial-v1"
        state="PREPARED_NOT_ART"
        original_v3_sha256=$sha
        source_file=$studio.File
        audited_code_commit=$codeCommit
        model=$Model
        model_requests=0
        art="HOLD"
        official_adoptions=0
        formal_331_993="NOT_RUN"
        minecraft="FORBIDDEN"
        human_gui_authoring="NOT_PERFORMED"
        source_modified=$false
    }
    $manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $trial "P2_SAFE_PREPARE.json") -Encoding UTF8
    if ($PrepareOnly) {
        Write-Host ("P2_PAIRED_OPERATOR_PREPARE_PASS_NO_MODEL_NO_BLENDER: " + $trial)
        return
    }

    $tags=$null
    try {
        $tags=Invoke-RestMethod -Uri "http://127.0.0.1:11434/api/tags" -Method Get -TimeoutSec 5
    } catch {
        $installed = Get-Command ollama.exe -ErrorAction SilentlyContinue
        $ollamaPath = if ($installed -and $installed.Source) {$installed.Source} else {
            Join-Path $env:LOCALAPPDATA "Programs\Ollama\ollama.exe"
        }
        if (-not (Test-Path -LiteralPath $ollamaPath -PathType Leaf)) {
            throw "LOCAL_OLLAMA_NOT_INSTALLED_OR_RUNNING"
        }
        Start-Process -FilePath $ollamaPath -ArgumentList "serve" -WindowStyle Hidden | Out-Null
        for ($i=0;$i -lt 12;$i++) {
            Start-Sleep -Seconds 2
            try {
                $tags=Invoke-RestMethod -Uri "http://127.0.0.1:11434/api/tags" -Method Get -TimeoutSec 3
                break
            } catch {}
        }
        if ($null -eq $tags) { throw "LOCAL_OLLAMA_SERVER_NOT_READY" }
    }
    $modelNames=@($tags.models | ForEach-Object {$_.name})
    if (-not ($modelNames -contains $Model)) {
        throw ("LOCAL_QWEN_MODEL_NOT_FOUND: " + $Model + ". Installed: " + ($modelNames -join ", "))
    }

    $proposal = Join-Path $trial "P2_TWO_NATIVE_EDITOR_ROLES_UNAPPROVED.json"
    Write-Host "ONE_Ollama_Tool_Call: bounded native Blender author actions only, NO Python code."
    $args1 = @($python.Prefix) + @(
        (Join-Path $trial $paths["propose"]),
        "--out", $proposal, "--model", $Model)
    & $python.Exe @args1
    if ($LASTEXITCODE -ne 0) {
        Write-Warning "LOCAL_MODEL_ACTIONS_REJECTED_ART_HOLD. No geometry was generated."
        Open-Evidence $trial
        exit 2
    }

    $study = Join-Path $trial "P2_NATIVE_PAIRED_OPERATOR_NON_ART"
    Write-Host "Applying validated native Blender edit operators to a SEPARATE file."
    & $blender --background --factory-startup --python (Join-Path $trial $paths["operator"]) -- --source $studio.File --actions $proposal --out $study
    if ($LASTEXITCODE -ne 0) {
        throw "NATIVE_BLENDER_EDITOR_TRIAL_FAILED"
    }

    $review = Join-Path $trial "P2_THREE_REAL_CYCLES_NON_ART"
    Write-Host "Rendering three true Cycles non-art views from the saved native study."
    & $blender --background --factory-startup --python (Join-Path $trial $paths["review"]) -- --source (Join-Path $study "P2_NATIVE_EDITOR_PAIRED_STUDY_UNAPPROVED.blend") --out $review
    if ($LASTEXITCODE -ne 0) {
        throw "THREE_VIEW_NATIVE_CYCLES_TRIAL_FAILED"
    }
    $reportPath=Join-Path $review "P2_NATIVE_PAIRED_THREE_VIEW_REPORT.json"
    if (-not (Test-Path -LiteralPath $reportPath -PathType Leaf)) { throw "NATIVE_3_VIEW_REPORT_NOT_FOUND" }
    $report=Get-Content -LiteralPath $reportPath -Raw | ConvertFrom-Json
    if ($report.art -ne "HOLD" -or $report.official_adoptions -ne 0 -or
        $report.minecraft -ne "FORBIDDEN" -or $report.true_city -ne $false) {
        throw "MODEL_TRIAL_PROVENANCE_OR_POLICY_INVALID"
    }
    if ((Get-HexHash $studio.File) -ne $sha) {throw "ORIGINAL_V3_CHANGED"}
    $html = Join-Path $review "OPEN_REAL_THREE_VIEW_NON_ART.html"
    if (Test-Path -LiteralPath $html -PathType Leaf) {
        try { Start-Process -FilePath $html | Out-Null } catch {}
    }
    Open-Evidence $review
    Write-Host ("P2_NATIVE_OPERATOR_FIRST_PAIR_COMPLETE_TECH_ONLY_ART_HOLD: " + $review)
} catch {
    Write-Error ("P2_NATIVE_OPERATOR_LOCAL_TRIAL_SAFE_STOP: " + $_.Exception.Message)
    exit 1
}
